// Paging: Mapping Virtual Address (VA) to Physical Address (PA)

#define PAGE_SHIFT 12  // 4KB pages
#define PAGE_SIZE (1 << PAGE_SHIFT)
typedef uintptr_t address_t;

// Context Register (per process)
address_t PTBR = 0x100000; // Page Table Base Register

// 1. Virtual Address used by Process
address_t virtual_addr = 0x7FF01234;

// 2. Decompose VA
address_t VPN = virtual_addr >> PAGE_SHIFT;   // Virtual Page Number
address_t Offset = virtual_addr & (PAGE_SIZE - 1);

// 3. Page Table Lookup (PTE address calculation)
// Assuming 64-bit PTEs (8 bytes)
address_t PTE_addr = PTBR + (VPN * 8);

// 4. Extract Physical Frame Number (PFN)
uint64_t PTE_val = /* Read memory at PTE_addr */;
uint64_t PFN = PTE_val >> 12; // Assuming lowest 12 bits are flags

// 5. Construct Physical Address (PA)
address_t physical_addr = (PFN << PAGE_SHIFT) | Offset;
